import traceback
from robot.running import EXECUTION_CONTEXTS
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.robotframework import RobotApi
from robot.utils.robottime import get_timestamp


logger = custom_logger('ettf.robot_handlers')


def with_callback_name(callback_name, append_class_name=False):
    def name_wrapper(named_object):
        name = callback_name
        if append_class_name and hasattr(named_object, '__self__'):
            name += ' [{}]'.format(named_object.__self__.__class__.__name__)
        named_object.__callback_name = name
        return named_object
    return name_wrapper


def get_callback_name(callback):
    if hasattr(callback, '__callback_name'):
        return callback.__callback_name
    elif hasattr(callback, '__name__'):
        return callback.__name__
    return callback.__class__.__name__


class DynamicKeyword(object):
    def __init__(self, name, result=None):
        self.kw = RobotApi().create_model_keyword(name)
        if result:
            self.kw.result = result

    def __enter__(self, *args, **kwargs):
        EXECUTION_CONTEXTS.current.start_keyword(self.kw)
        return self

    def __exit__(self, *args, **kwargs):
        EXECUTION_CONTEXTS.current.end_keyword(self.kw)

    def passed(self):
        self.kw.passed = True
        self.kw.endtime = get_timestamp()

    def failed(self):
        self.kw.passed = False
        self.kw.endtime = get_timestamp()

    def is_passed(self):
        return self.kw.passed


class RobotKeywordDecorator(object):
    def __init__(self, result=None):
        self._result = result

    def __call__(self, callback):
        with DynamicKeyword(get_callback_name(callback), self._result) as keyword:
            try:
                self._before_callback(callback)
                callback()
                keyword.passed()
                self._after_callback(callback)
            except Exception:
                keyword.passed()
                logger.error(traceback.format_exc())

    def _before_callback(self, callback):
        pass

    def _after_callback(self, callback):
        pass


class TeardownKeywordDecorator(RobotKeywordDecorator):
    def _before_callback(self, callback):
        logger.debug('{} is going to be torn down'.format(callback))

    def _after_callback(self, callback):
        logger.debug('{} is torn down'.format(callback))
